import pandas as pd
import numpy as np

# Load the data
data = pd.read_csv('chunks_csv/moran_local_2021_crime.csv')
adjacency = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Handle missing values
data['Crime_value'] = data['Crime_value'].fillna(data['Crime_value'].mean())

# Compute neighborhood crime rates
adjacency_list = adjacency.groupby('borough')['neighbor'].apply(lambda x: x.tolist()).to_dict()
neighborhood_crime_rates = {}
for borough, neighbors in adjacency_list.items():
    neighborhood_crime_rates[borough] = np.mean([data.loc[data['borough'] == neighbor, 'Crime_value'].mean() for neighbor in neighbors])

# Identify hot and cold spots
potential_hot_spots = []
potential_cold_spots = []
for index, row in data.iterrows():
    if row['Crime_value'] > neighborhood_crime_rates[row['borough']]:
        potential_hot_spots.append(row['borough'])
    elif row['Crime_value'] < neighborhood_crime_rates[row['borough']]:
        potential_cold_spots.append(row['borough'])

# Compute statistical significance
def permutation_test(borough):
    crime_rates = data.loc[data['borough'] != borough, 'Crime_value']
    shuffled_crime_rates = np.random.permutation(crime_rates)
    shuffled_neighborhood_crime_rate = np.mean(shuffled_crime_rates)
    observed_difference = data.loc[data['borough'] == borough, 'Crime_value'].mean() - neighborhood_crime_rates[borough]
    p_value = np.mean(np.abs(shuffled_neighborhood_crime_rate - observed_difference) > np.abs(data.loc[data['borough'] == borough, 'Crime_value'].mean() - neighborhood_crime_rates[borough]))
    return p_value

# Classify boroughs
hot_spots = []
cold_spots = []
for borough in potential_hot_spots:
    p_value = permutation_test(borough)
    if p_value < 0.05:
        hot_spots.append((borough, 'HH', permutation_test(borough)))
    else:
        hot_spots.append((borough, 'HH', permutation_test(borough)))
for borough in potential_cold_spots:
    p_value = permutation_test(borough)
    if p_value < 0.05:
        cold_spots.append((borough, 'LL', permutation_test(borough)))
    else:
        cold_spots.append((borough, 'LL', permutation_test(borough)))

# Report results
print(f'data_points_used = {data.shape[0]}')
if hot_spots:
    print(f'FINAL ANSWER: {", ".join([f"{borough} ({statistic}, test statistic = {test_statistic}, significance measure = {significance_measure})" for borough, statistic, (test_statistic, significance_measure) in hot_spots])}')
else:
    print(f'FINAL ANSWER: none')
if cold_spots:
    print(f'FINAL ANSWER: {", ".join([f"{borough} ({statistic}, test statistic = {test_statistic}, significance measure = {significance_measure})" for borough, statistic, (test_statistic, significance_measure) in cold_spots])}')
else:
    print(f'FINAL ANSWER: none')
